/**
 * The flows that matter (#17), against the real production build.
 *
 * The puzzle is generated by the app, not injected: there is no test-only seam
 * in the bundle, and a seam is not needed — the board is readable from the DOM,
 * and the test solves it with the same engine the app ships. That keeps the
 * production bundle the thing under test, and it means a generator that starts
 * emitting unsolvable puzzles fails here rather than passing quietly.
 *
 * One puzzle, one page, steps in order: generation is the slowest thing the app
 * does, and paying for it once per browser is the difference between a suite
 * that runs on every push and one that gets skipped.
 */

import { expect, test, type Page } from '@playwright/test';
import { openCoach } from './coach';
import { boardCell, boardGrid } from './board';
import { Board } from '../../src/engine/board';
import { firstFinding, solveBruteForce } from '../../src/engine/solver';
import type { Digit } from '../../src/engine/types';

test.describe.configure({ mode: 'serial' });

interface DomCell {
  index: number;
  given: boolean;
  value: number | null;
  notes: number[];
}

/** The board as the player sees it, read back out of the grid. */
async function readBoard(page: Page): Promise<DomCell[]> {
  return page.locator('main [data-cell]').evaluateAll((nodes) =>
    nodes
      .map((node) => {
        const element = node as HTMLElement;
        const digit = element.querySelector('span.digit')?.textContent?.trim() ?? '';
        const label = element.getAttribute('aria-label') ?? '';
        // "r3c4, empty, notes 1, 4, 9" — and possibly a sentence after it about
        // the ones a placement has killed, which is not part of the list.
        const listed = /notes ([\d,\s]+)/.exec(label)?.[1] ?? '';
        const notes = listed
          .split(',')
          .map((part) => Number(part.trim()))
          .filter((n) => n >= 1 && n <= 9);
        return {
          index: Number(element.dataset.cell),
          given: element.hasAttribute('data-given'),
          value: digit === '' ? null : Number(digit),
          notes,
        };
      })
      .sort((a, b) => a.index - b.index),
  );
}

/** True when two cells share a row, a column or a box. */
function sees(a: number, b: number): boolean {
  if (a === b) return false;
  const [ra, ca] = [Math.floor(a / 9), a % 9];
  const [rb, cb] = [Math.floor(b / 9), b % 9];
  return (
    ra === rb ||
    ca === cb ||
    (Math.floor(ra / 3) === Math.floor(rb / 3) && Math.floor(ca / 3) === Math.floor(cb / 3))
  );
}

/** A digit not yet placed anywhere `cell` can see, so noting it is legal. */
function pickAbsentDigit(cells: DomCell[], cell: number): number {
  const seen = new Set(
    cells.filter((other) => sees(cell, other.index)).map((other) => other.value),
  );
  for (let digit = 1; digit <= 9; digit++) if (!seen.has(digit)) return digit;
  throw new Error('no digit is free for that cell');
}

async function enter(page: Page, cell: number, digit: number): Promise<void> {
  await boardCell(page, cell).click();
  await page.keyboard.press(String(digit));
}

async function startEasyGame(page: Page): Promise<void> {
  await page.goto('/');
  await page.getByRole('button', { name: 'New puzzle' }).click();
  await page.getByRole('button', { name: 'Easy', exact: true }).click();
  // Generation runs in a worker and retries until the rating matches.
  await expect(boardGrid(page)).toBeVisible({ timeout: 60_000 });
}

test.describe('one puzzle, end to end', () => {
  test('generates a puzzle and opens it on the board', async ({ page }) => {
    await startEasyGame(page);

    const cells = await readBoard(page);
    expect(cells).toHaveLength(81);
    expect(cells.filter((cell) => cell.given).length).toBeGreaterThan(16);
    await expect(page.getByRole('timer')).toBeVisible();
  });

  test('climbs the disclosure ladder one rung at a time', async ({ page }) => {
    await startEasyGame(page);
    const coach = await openCoach(page);

    // Nothing is disclosed until the player asks (R7). The ladder itself only
    // appears once there is a rung to be on — on a phone it is board otherwise.
    await expect(coach.getByRole('button', { name: 'Where should I look?' })).toBeVisible();
    await expect(coach.getByText(/Hidden single|Naked single/)).toHaveCount(0);

    await coach.getByRole('button', { name: 'Where should I look?' }).click();
    await expect(coach.getByLabel('Disclosure level 1 of 4')).toBeVisible();

    await coach.getByRole('button', { name: /Name the technique/ }).click();
    await expect(coach.getByLabel('Disclosure level 2 of 4')).toBeVisible();

    await coach.getByRole('button', { name: /Show me the cells/ }).click();
    await expect(coach.getByLabel('Disclosure level 3 of 4')).toBeVisible();
  });

  test('checks the notes the player made, and changes none of them', async ({ page }) => {
    await startEasyGame(page);
    const before = await readBoard(page);

    // A mark that is certainly wrong: a digit already placed in a peer. Any
    // empty cell with a filled peer will do — which row that turns out to be is
    // the generator's business, not the test's.
    const pair = before
      .filter((cell) => !cell.given && cell.value === null)
      .flatMap((cell) => {
        const peer = before.find((other) => sees(cell.index, other.index) && other.value !== null);
        return peer === undefined ? [] : [{ cell: cell.index, digit: peer.value as Digit }];
      })[0]!;

    await page.getByRole('button', { name: 'Notes off' }).click();
    await enter(page, pair.cell, pair.digit);

    const coach = await openCoach(page);
    await coach.getByRole('button', { name: 'Check my notes' }).click();
    await expect(coach.getByText(/need a second look/)).toBeVisible();

    // R8: the review reports, it never corrects.
    const after = await readBoard(page);
    expect(after[pair.cell].notes).toContain(pair.digit);
  });

  test('survives being killed mid-game, undo history included (R5)', async ({ page }) => {
    await startEasyGame(page);
    const start = await readBoard(page);
    const blanks = start.filter((cell) => !cell.given && cell.value === null).slice(0, 3);

    for (const cell of blanks) await enter(page, cell.index, 5);
    const played = await readBoard(page);

    // The store autosaves on a debounce; a reload is the honest way to wait for
    // it, because a game that only survives a graceful exit has not survived.
    await page.waitForTimeout(1500);
    await page.reload();
    await expect(boardGrid(page)).toBeVisible();

    expect(await readBoard(page)).toEqual(played);

    // The move log came back with the board: undo still walks it backwards.
    await page.getByRole('button', { name: 'Undo' }).click();
    const undone = await readBoard(page);
    expect(undone[blanks[2].index].value).toBeNull();

    await page.getByRole('button', { name: 'Redo' }).click();
    expect(await readBoard(page)).toEqual(played);
  });

  test('flags the notes a placement killed, and clears them on request', async ({ page }) => {
    await startEasyGame(page);
    const start = await readBoard(page);

    // Note a digit in an empty cell, then place that same digit in one of its
    // peers: the note is now dead by the rules, and nothing but the player's
    // own move made it so.
    const empty = start.find((cell) => !cell.given && cell.value === null)!;
    const peer = start.find(
      (cell) => !cell.given && cell.value === null && sees(empty.index, cell.index),
    )!;
    const digit = pickAbsentDigit(start, empty.index);

    await page.getByRole('button', { name: 'Notes off' }).click();
    await enter(page, empty.index, digit);
    await page.getByRole('button', { name: 'Notes on' }).click();
    await enter(page, peer.index, digit);

    // Flagged on the board, and said in words for anyone not reading colour.
    await expect(boardCell(page, empty.index).locator('[data-stale]')).toHaveCount(1);
    await expect(boardCell(page, empty.index)).toHaveAttribute(
      'aria-label',
      new RegExp(`Notes ${digit} can no longer be true here`),
    );

    // One press to clear, one undo to get them back: the marks stay the
    // player's either way. The press is on the keypad's own eraser, which
    // carries the clear while anything is dead — the near door, reachable
    // without opening the coach at all. Scoped to the pad on purpose: from
    // `tablet` up the coach rests as a bar rather than behind a trigger, so
    // its own copy of this button is on screen too, and an unscoped locator
    // would pass here while proving nothing about the key this test is for.
    const keypad = page.getByRole('group', { name: /^Keypad/ });
    await keypad.getByRole('button', { name: /^Clear dead notes$/ }).click();
    expect((await readBoard(page))[empty.index].notes).toEqual([]);

    // And with the notes gone the key is an eraser again, so the pad is back
    // to what it was rather than stuck in a mode.
    await expect(keypad.getByRole('button', { name: 'Erase cell' })).toBeVisible();

    await page.getByRole('button', { name: 'Undo' }).click();
    expect((await readBoard(page))[empty.index].notes).toEqual([digit]);
  });

  test('the green highlight survives moving the caret', async ({ page }) => {
    await startEasyGame(page);
    const cells = await readBoard(page);

    // Any given is guaranteed to light something up when selected; the
    // puzzle's own givens are what makes the choice safe rather than
    // hardcoding a digit that might not appear on this board at all.
    const given = cells.find((cell) => cell.given)!;
    // An empty cell can never itself hold the given's digit — so moving the
    // caret there can only prove the highlight held, rather than landing on
    // a cell that was always going to read as matched regardless of whether
    // arming it is sticky at all (a fixed coordinate risks exactly that on
    // the ~4-5% of boards where it happens to already carry the same digit).
    const empty = cells.find((cell) => cell.value === null)!;

    // The grid drives the green now, not the keypad (R3): selecting a cell
    // that holds a digit is the arm/clear decision.
    await boardCell(page, given.index).click();
    const lit = page.locator('main [role="gridcell"][data-match="true"]');
    await expect(lit.first()).toBeVisible();
    const before = await lit.count();

    // Moving the caret onto an empty cell is not an arm/clear decision, so it
    // must leave the highlight exactly as it was.
    await boardCell(page, empty.index).click();
    await expect(lit).toHaveCount(before);

    // Selecting the same lit cell again is the other half of the rule: it
    // clears rather than leaving the green stuck on.
    await boardCell(page, given.index).click();
    await expect(lit).toHaveCount(0);
  });

  test('plays a puzzle through to the end', async ({ page }) => {
    await startEasyGame(page);
    const cells = await readBoard(page);

    const values = cells.map((cell) => (cell.value === null ? null : (cell.value as Digit)));
    const solution = solveBruteForce(Board.fromValues(values));
    expect(solution, 'the generated puzzle must be solvable').not.toBeNull();

    for (const cell of cells) {
      if (cell.value !== null) continue;
      await enter(page, cell.index, solution!.values[cell.index]!);
    }

    await expect(page.getByText('Solved', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'New game' })).toBeVisible();

    // The board says so itself, and this is the only place it can be checked
    // for real: jsdom runs no animation, so a unit test can hold which cells
    // were told to flip but never that any of them ended up gold. `toHaveCSS`
    // retries, which is what lets it wait out the wave rather than racing it.
    await expect(boardCell(page, 0)).toHaveCSS('background-color', 'rgb(58, 167, 111)');
    // The bottom row lands last — if the shower were a flash, this cell would
    // not be the one still arriving.
    await expect(boardCell(page, 80)).toHaveCSS('background-color', 'rgb(58, 167, 111)');

    // The recap reports what the coach was asked for. This puzzle was solved
    // from the solution, so the honest answer is "nothing".
    await expect(page.getByText(/without asking the coach anything/)).toBeVisible();

    // And a solved board belongs under Finished, not under In progress.
    await page.getByRole('button', { name: 'Your games' }).click();
    await expect(page.getByText('Finished')).toBeVisible();
    await expect(page.getByText(/Finished in \d/)).toBeVisible();
    await expect(page.getByText('Nothing on the desk')).toBeVisible();
  });
});

/*
 * The layout invariant, measured rather than inferred from the shape of the
 * tree. The spec states it as a pixel property — "board pixel height is
 * constant from first move to last" — and the unit canary beside `GameView`
 * cannot check it, because jsdom does no layout. This is where the property
 * itself is asserted, against the real build, in a browser.
 *
 * Phone only, deliberately: above `sm` the coach is a static bar that
 * legitimately grows when it has something to say, and the page scrolls. The
 * one-screen, nothing-moves promise belongs to the phone layout.
 */
test.describe('the board never gives up height', () => {
  test.skip(({ isMobile }) => !isMobile, 'the one-screen layout is the phone layout');

  // Short on purpose. The grid is `aspect-square w-full`, so on a tall phone
  // its height is derived from the screen's *width* and a sibling that steals
  // vertical space comes out of the slack instead — the board would hold its
  // size here for a reason that has nothing to do with the invariant, and the
  // test would pass on exactly the code it exists to reject. At this height
  // the board is the piece that gives, which is the whole design.
  const SHORT_PHONE = { width: 412, height: 560 };

  test('stays the same size in every state a game can be in', async ({ page }) => {
    await page.setViewportSize(SHORT_PHONE);
    await startEasyGame(page);
    const grid = boardGrid(page);
    const heightNow = async (): Promise<number> => {
      const box = await grid.boundingBox();
      expect(box, 'the grid has to be on screen to be measured').not.toBeNull();
      return box!.height;
    };

    const atRest = await heightNow();
    expect(atRest).toBeGreaterThan(0);
    // The test's own precondition, asserted rather than assumed: the board has
    // to be height-bound for any of the measurements below to mean anything.
    expect(
      atRest,
      'the board must be sized by the height it was left, not by the screen width',
    ).toBeLessThan(SHORT_PHONE.width - 24);

    // The coach badge lit. A digit the solution contradicts is a nudge the
    // trigger machinery raises without a detector pass, and the badge is an
    // `after:` pseudo-element on a real flow child of the header now, not
    // something floating over the board where it could never have moved
    // anything — this is the case that actually proves lighting it does not
    // grow the header and push the board down.
    const cells = await readBoard(page);
    const values = cells.map((cell) => (cell.value === null ? null : (cell.value as Digit)));
    const solution = solveBruteForce(Board.fromValues(values));
    expect(solution, 'the generated puzzle must be solvable').not.toBeNull();
    const spare = cells.find((cell) => !cell.given && cell.value === null)!;
    const wrong = ((solution!.values[spare.index]! % 9) + 1) as Digit;
    await enter(page, spare.index, wrong);
    const trigger = page.getByRole('button', { name: /has something for you/ });
    await expect(trigger).toBeVisible();
    expect(await heightNow()).toBeCloseTo(atRest, 1);

    // The dot is an `::after` pseudo-element positioned `absolute` — it only
    // lands on the icon because the button itself is `position: relative`.
    // Drop that class in a future refactor and the pseudo-element resolves
    // against the next positioned ancestor up the tree instead — silently,
    // since the `top-0 right-0` in the CSS never changes, only what it's
    // relative to does. The button's own computed position is the one
    // property that actually catches that regression.
    const [triggerPosition, dotPosition] = await trigger.evaluate((el) => [
      getComputedStyle(el).position,
      getComputedStyle(el, '::after').position,
    ]);
    expect(triggerPosition, 'the trigger must be its own containing block').toBe('relative');
    expect(dotPosition, 'the badge dot must be positioned against the trigger').toBe('absolute');

    // Cleared again before the next state, so each one is measured on its own
    // rather than on the accumulation of the ones before it.
    await boardCell(page, spare.index).click();
    await page.keyboard.press('Backspace');
    expect(await heightNow()).toBeCloseTo(atRest, 1);

    // Dead notes on the board: a note, then the peer placement that kills it.
    // The strike-through is drawn inside a cell whose size the grid fixes, and
    // the eraser it offers lives in the coach panel rather than in a row of
    // its own — which is the regression this whole invariant exists for.
    const start = await readBoard(page);
    const noted = start.find((cell) => !cell.given && cell.value === null)!;
    const peer = start.find(
      (cell) => !cell.given && cell.value === null && sees(noted.index, cell.index),
    )!;
    const digit = pickAbsentDigit(start, noted.index);
    await page.getByRole('button', { name: 'Notes off' }).click();
    await enter(page, noted.index, digit);
    await page.getByRole('button', { name: 'Notes on' }).click();
    await enter(page, peer.index, digit);
    await expect(boardCell(page, noted.index).locator('[data-stale]')).toHaveCount(1);
    expect(await heightNow()).toBeCloseTo(atRest, 1);

    // And with the sheet open over the keypad, which is the state that used to
    // push the board around the most.
    await openCoach(page);
    expect(await heightNow()).toBeCloseTo(atRest, 1);
  });
});

/*
 * Invariant 9 in its general form, not just the phone case above: whatever
 * the tier, nothing that comes and goes during play may resize the board.
 * Unlike the phone-only describe above, this runs in every project — the
 * tablet's stacked layout, the laptop's board-and-coach pair, and the
 * desktop tier's third lesson column are three more places the board could
 * have been made to move, and none of them were exercised by a test before
 * this.
 */
test('the board keeps its box whatever the coach is doing', async ({ page }, testInfo) => {
  await startEasyGame(page);
  const grid = boardGrid(page);
  const atRest = (await grid.boundingBox())!;

  await openCoach(page);
  const withCoach = (await grid.boundingBox())!;
  expect(withCoach.width).toBeCloseTo(atRest.width, 1);
  expect(withCoach.height).toBeCloseTo(atRest.height, 1);

  await page.getByRole('button', { name: /where should i look/i }).click();
  const withHint = (await grid.boundingBox())!;
  expect(withHint.width).toBeCloseTo(atRest.width, 1);
  expect(withHint.height).toBeCloseTo(atRest.height, 1);

  // The state the desktop tier exists to introduce, and the only one that
  // changes the third column's content: level 2 names a technique, which
  // swaps a fourteen-row index for a full lesson — two prose sections and a
  // second 81-cell grid. Nothing above measured it. `openCoach` performs no
  // click at all above 640px, so `withCoach` re-measures the resting state
  // there, and a level-1 hint only adds a sentence inside a column that was
  // already on screen at its final width. Unguarded by tier: escalating
  // works everywhere, and it gives the tablet and the laptop a genuinely
  // second state too.
  await page.getByRole('button', { name: /name the technique/i }).click();
  const withLesson = (await grid.boundingBox())!;
  expect(withLesson.width).toBeCloseTo(atRest.width, 1);
  expect(withLesson.height).toBeCloseTo(atRest.height, 1);

  // The third content state: a lesson the player opened themselves. It
  // arrives by a different route than the coach's — back to the index, then
  // a row — and the column has to hold its box across both moves, not just
  // across the swap the coach causes. Desktop only, because the column is.
  if (testInfo.project.name === 'wide') {
    const column = page.getByTestId('lesson-column');
    await column.getByRole('button', { name: 'Back' }).click();
    const withIndex = (await grid.boundingBox())!;
    expect(withIndex.width).toBeCloseTo(atRest.width, 1);
    expect(withIndex.height).toBeCloseTo(atRest.height, 1);

    await column.getByRole('button', { name: /Remote pairs/ }).click();
    const withBrowsed = (await grid.boundingBox())!;
    expect(withBrowsed.width).toBeCloseTo(atRest.width, 1);
    expect(withBrowsed.height).toBeCloseTo(atRest.height, 1);
  }
});

/*
 * The `6rem` header-height budget in `GameLayout`'s lesson column
 * (`max-h-[calc(100dvh-6rem)]`) was reasoned about, never measured, and
 * nothing pins it — a header that grows would silently push the column's
 * bottom edge off screen. This is that pin: a lesson long enough to
 * genuinely exceed the cap (proven, not assumed, by checking the box is
 * shorter than its content), with the column's own bottom edge asserted to
 * stay inside the viewport regardless.
 */
test.describe('the lesson column stays inside the viewport', () => {
  test('never runs its bottom edge past the fold', async ({ page }, testInfo) => {
    test.skip(testInfo.project.name !== 'wide', 'the lesson column only exists on the desktop tier');

    await startEasyGame(page);
    const coach = await openCoach(page);

    // Level 2 is where a technique gets named (R7), which is what swaps the
    // sidebar's `TechniqueIndex` for a full `LessonBody` — what/why/example,
    // the tallest a lesson gets.
    await coach.getByRole('button', { name: 'Where should I look?' }).click();
    await coach.getByRole('button', { name: /Name the technique/ }).click();

    const lesson = page.getByTestId('lesson-column');
    await expect(lesson).toBeVisible();

    const [scrollHeight, clientHeight] = await lesson.evaluate((el) => [
      el.scrollHeight,
      el.clientHeight,
    ]);
    expect(
      scrollHeight,
      'the lesson must be taller than its box, or the cap below is not being tested at all',
    ).toBeGreaterThan(clientHeight);

    const box = (await lesson.boundingBox())!;
    const viewport = page.viewportSize()!;
    expect(
      box.y + box.height,
      "the column's bottom edge must stay inside the viewport",
    ).toBeLessThanOrEqual(viewport.height);
  });

  test('scrolls on its own, and takes neither the page nor the board with it', async ({
    page,
  }, testInfo) => {
    test.skip(testInfo.project.name !== 'wide', 'the lesson column only exists on the desktop tier');

    await startEasyGame(page);
    const coach = await openCoach(page);
    await coach.getByRole('button', { name: 'Where should I look?' }).click();
    await coach.getByRole('button', { name: /Name the technique/ }).click();

    const lesson = page.getByTestId('lesson-column');
    const grid = boardGrid(page);
    const before = (await grid.boundingBox())!;
    const pageScrollBefore = await page.evaluate(() => window.scrollY);

    // A real wheel over the column, which is the gesture that used to take
    // the whole page with it once the column ran out of content.
    const box = (await lesson.boundingBox())!;
    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    await page.mouse.wheel(0, 400);

    // It moved — otherwise the two assertions below would hold for a column
    // that simply cannot scroll, and prove nothing.
    // Polled, not read once: the wheel is dispatched asynchronously and the
    // scroll lands a frame later.
    await expect
      .poll(async () => lesson.evaluate((el) => el.scrollTop))
      .toBeGreaterThan(0);
    expect(await page.evaluate(() => window.scrollY)).toBe(pageScrollBefore);

    const after = (await grid.boundingBox())!;
    expect(after.y).toBeCloseTo(before.y, 1);
    expect(after.height).toBeCloseTo(before.height, 1);
  });
});

/*
 * The header is the crowded surface now that the coach trigger lives there
 * (five siblings competing for one row), and a manual measurement at a couple
 * of widths is what rots the next time a control or a locale is added. This
 * pins the two properties that measurement checked: the 44px touch-target
 * floor holds on every header button, and the difficulty badge never reaches
 * the timer, at the header's narrowest supported width and with the timer at
 * its widest — a long game, not a fresh one, is the case that actually eats
 * into the badge's share of the row.
 */
test.describe('the header at its narrowest', () => {
  test.skip(({ isMobile }) => !isMobile, 'the crowded header only exists on a narrow phone');

  test('keeps every control at the 44px floor and the badge clear of the timer', async ({
    page,
  }) => {
    // Installed before navigation, per Playwright's own guidance, so
    // `Date.now()` — what the shared second-hand in `clock.ts` reads — can be
    // pushed forward without actually waiting an hour for the timer to widen.
    await page.clock.install();
    await page.setViewportSize({ width: 320, height: 700 });
    await startEasyGame(page);

    // "1:02:03" is close to the widest the timer ever gets; it's the width
    // that actually eats into the badge's share of the row, not the width at
    // 0:00 a fresh game starts from.
    await page.clock.fastForward('01:02:03');

    const header = page.locator('header');
    const buttons = header.getByRole('button');
    const count = await buttons.count();
    expect(count, 'back, pause, the coach trigger and the overflow menu').toBe(4);
    for (let i = 0; i < count; i++) {
      const box = await buttons.nth(i).boundingBox();
      expect(box, `header button ${i} must be on screen to be measured`).not.toBeNull();
      expect(box!.width, `header button ${i} width`).toBeGreaterThanOrEqual(44);
      expect(box!.height, `header button ${i} height`).toBeGreaterThanOrEqual(44);
    }

    // The badge's own wrapper — the one `overflow-hidden` div in the header —
    // is what actually bounds what's painted: `DifficultyBadge`'s own root
    // sizes to its full content regardless of the room it's given, so
    // measuring the wrapper is what proves nothing is painted past it, not
    // what the badge would take up if it could have all the room it wanted.
    const badge = header.locator('> div');
    const timer = header.getByRole('timer');
    const badgeBox = await badge.boundingBox();
    const timerBox = await timer.boundingBox();
    expect(badgeBox, 'the badge must be on screen to be measured').not.toBeNull();
    expect(timerBox, 'the timer must be on screen to be measured').not.toBeNull();
    expect(
      badgeBox!.x + badgeBox!.width,
      'the badge must never reach the timer, even at its narrowest',
    ).toBeLessThanOrEqual(timerBox!.x);
  });
});

test.describe('drills', () => {
  test('sets a challenge, and confirms it only when the board shows it', async ({ page }) => {
    await startEasyGame(page);
    let coach = await openCoach(page);

    await coach.getByRole('button', { name: 'Set me a challenge' }).click();
    await expect(coach.getByText(/There is a .* on this board/)).toBeVisible();

    // An easy board's first finding is a single, so applying it is placing
    // the digit it proves — read with the same engine call the app itself
    // makes (`nextFinding` is `firstFinding` over exactly this board), not by
    // guessing which cell the drill meant.
    const cells = await readBoard(page);
    const values = cells.map((cell) => (cell.value === null ? null : (cell.value as Digit)));
    const board = Board.fromValues(values);
    const solution = solveBruteForce(board);
    expect(solution).not.toBeNull();
    const finding = firstFinding(board);
    expect(finding).not.toBeNull();
    // An elimination-only technique places nothing, and the loop below would
    // then satisfy no drill and time out on the last assertion with a cause
    // nobody would find. Say it here instead.
    expect(
      finding!.placements.length,
      'this test applies the finding by placing its digits',
    ).toBeGreaterThan(0);

    // Scoped to the interactive board: on the desktop tier the drill's own
    // level-2 naming swaps the lesson column to a worked `Example`, whose
    // illustration spotlights cells on purpose — that is not the board this
    // assertion is about.
    const spotlight = page.locator('main [data-spotlight]');
    // Nothing is spotlighted by a level-2 disclosure: the technique is named,
    // the cells are not (R7).
    await expect(spotlight).toHaveCount(0);

    // The sheet is a real modal on a phone and sits over the board while
    // open, so touching a cell means closing it first — the same trade a
    // player makes. `Escape` is a no-op on the desktop bar, which never
    // covered the board in the first place.
    await page.keyboard.press('Escape');

    // A wrong move does not satisfy a drill. Asserted as the challenge text
    // still standing, not as "applied by you" absent: the detector is behind
    // a debounce (below), so a fresh negative check resolves at its first
    // poll, before that debounce could possibly have run, and would pass
    // exactly the same way if the wrong move had wrongly satisfied it.
    // `toBeVisible` on the mutually-exclusive text the panel would have
    // replaced is the one of the two that a same-tick bug could actually
    // fail.
    const empty = cells.find((cell) => cell.value === null)!;
    const wrong = ((solution!.values[empty.index]! % 9) + 1) as Digit;
    await enter(page, empty.index, wrong);
    coach = await openCoach(page);
    await expect(coach.getByText(/There is a .* on this board/)).toBeVisible();
    await page.keyboard.press('Escape');
    await boardCell(page, empty.index).click();
    await page.keyboard.press('Backspace');

    // Only the cell(s) the finding itself places, not the rest of the board:
    // filling every remaining cell would solve the puzzle outright, and a
    // solved game covers the header's coach trigger with its own "Solved"
    // sheet before this could reopen the coach to read it. Placing just the
    // finding's own digit is also the more exact proof — it is the move the
    // drill is actually about, not an accident of finishing the grid.
    for (const { cell, digit } of finding!.placements) {
      await enter(page, cell, digit);
    }

    coach = await openCoach(page);
    await expect(coach.getByText(/applied by you/)).toBeVisible();
  });
});

test.describe('the keyboard', () => {
  test('plays the game without the mouse', async ({ page }) => {
    await startEasyGame(page);
    const cells = await readBoard(page);
    const empty = cells.find((cell) => !cell.given && cell.value === null)!;

    // N is notes mode, so the same keystroke writes a mark rather than a digit.
    await page.keyboard.press('n');
    await expect(page.getByRole('group', { name: 'Keypad, notes mode' })).toBeVisible();
    await enter(page, empty.index, 4);
    expect((await readBoard(page))[empty.index].notes).toEqual([4]);

    await page.keyboard.press('n');
    await enter(page, empty.index, 4);
    expect((await readBoard(page))[empty.index].value).toBe(4);

    // U and R walk the same history the buttons do.
    await page.keyboard.press('u');
    expect((await readBoard(page))[empty.index].value).toBeNull();
    await page.keyboard.press('r');
    expect((await readBoard(page))[empty.index].value).toBe(4);

    // And the shortcut every player tries first.
    await page.keyboard.press('ControlOrMeta+z');
    expect((await readBoard(page))[empty.index].value).toBeNull();

    // 'h' opens the sheet itself on a narrow viewport (it is how a keyboard
    // player reaches a coach that a mouse would tap the header trigger for)
    // — read directly here rather than through `openCoach`, which clicks that
    // trigger: this test's whole point is that no pointer input is needed at
    // all.
    await page.keyboard.press('h');
    const coach = page.getByRole('region', { name: 'Coach' });
    await expect(coach.getByLabel('Disclosure level 1 of 4')).toBeVisible();
  });
});
